<template><section class="scr-card"><h3>{{ t('settings.persistence') }}</h3><NumericInput :model-value="Number(settings.historyLimit || 10)" :label="t('settings.historyLimit')" :min="1" :max="50" @update:model-value="value => update('historyLimit', value)" /><NumericInput :model-value="Number(settings.dnaLibraryLimit || 100)" :label="t('settings.dnaLimit')" :min="1" :max="100" @update:model-value="value => update('dnaLibraryLimit', value)" /><ToggleField :model-value="settings.rememberLocks === true" :label="t('settings.rememberLocks')" @update:model-value="value => update('rememberLocks', value)" /><label class="scr-field"><span>{{ t('settings.restoreMode') }}</span><select :value="settings.defaultRestoreMode" @change="update('defaultRestoreMode', $event.target.value)"><option value="exact">exact</option><option value="compatible">compatible</option></select></label></section></template>
<script setup>import { useStores } from "../../stores"; import ToggleField from "../common/ToggleField.vue"; import NumericInput from "../common/NumericInput.vue"; const stores = useStores(); const settings = stores.settings.state; const { t } = stores.i18n; const update = (field, value) => stores.command.send("updateSettings", [{ [field]: value }])</script>
